            <View style={[s.row, { justifyContent: "space-between" }]}>
              <Label size={20} bold>
                {x.personal.name}
              </Label>
              <Badge>
                {x.linkStatus === "active"
                  ? "Vínculo ativo"
                  : "Vínculo encerrado"}
              </Badge>
            </View>
            <Label muted>{x.mainGoal}</Label>
            <View style={{ marginTop: 16 }}>
              <Button
                onPress={() => router.push(`/acompanhamento/${x.id}` as Href)}
