            options={records.map((r) => ({
              value: r.id,
              label: formatDate(r.date),
            }))}
          />
          <Choices
            label="Período atual"
            value={b.id}
            onChange={setSecond}
            options={records.map((r) => ({
              value: r.id,
              label: formatDate(r.date),
            }))}
          />
          {technicalCriteria.map((c) => (
            <Card key={c}>
              <Label bold>{c}</Label>
              <View style={s.grid}>
                <View style={s.column}>
                  <Label muted>{formatDate(a.date)}</Label>
                  <Label>
                    {(a.data.criteria as Criterion[]).find(
                      (x) => x.criterion === c,
                    )?.current || "—"}
                  </Label>
                </View>
                <View style={s.column}>
                  <Label muted>{formatDate(b.date)}</Label>
                  <Label>
                    {(b.data.criteria as Criterion[]).find(
                      (x) => x.criterion === c,
                    )?.current || "—"}
                  </Label>
                  <Label size={11} muted>
                    Próxima ação:{" "}
                    {(b.data.criteria as Criterion[]).find(
