            </Notice>
            <View style={s.row}>
              {!studentView && !student.accountId && (
                <Button
                  onPress={async () => {
                    try {
                      const result = await api<{ code: string }>(
                        `/students/${id}/invite`,
                        "POST",
                      );
                      setInvitation(result.code);
                    } catch (e) {
                      setFailure(message(e));
                    }
                  }}
                >
                  Gerar convite
                </Button>
              )}
              <Button
                variant="secondary"
                onPress={async () => {
                  try {
                    await exportStudent(id, studentView);
                  } catch (e) {
                    setFailure(message(e));
                  }
                }}
