                <HistoricalDetail detail={h.detail} />
              </View>
            ))}
          </Card>
        </>
      )}
      {editing && (
        <Dialog title="Editar cadastro" onClose={() => setEditing(false)}>
          <StudentForm
            student={student}
            programs={programs ?? []}
            onSaved={() => {
              setEditing(false);
              void reload();
            }}
          />
        </Dialog>
      )}
      {record && (
        <Dialog
          title={recordNames[record.kind]}
          onClose={() => setRecord(null)}
        >
          <RecordForm
            studentId={id}
            {...record}
            onSaved={() => {
              setRecord(null);
              void reload();
            }}
          />
        </Dialog>
      )}
      {evaluation && (
        <Dialog
          title="Avaliação periódica"
          onClose={() => {
            setEvaluation(null);
            void reload();
          }}
        >
          <EvaluationForm
            student={student}
