            evaluation={evaluation === "new" ? undefined : evaluation}
            studentView={studentView}
            onSaved={() => {
              setEvaluation(null);
              void reload();
            }}
          />
        </Dialog>
      )}
      {invitation && (
        <Dialog title="Convite para o aluno" onClose={() => setInvitation("")}>
