{"behavior":[{"confidence":"observed","description":"Contém JSX que referencia Button, Card, Field, Fields, Label, Notice; a execução visual não foi testada.","evidence":[{"end_line":356,"snippet":"export function RecordForm({
  studentId,
  kind,
  record,
  onSaved,
}: {
  studentId: string;
  kind: RecordKind;
  record?: TrackingRecord;
  onSaved: () => void;
}) {
  const [date, setDate] = useState(record?.date ?? today());
  const [values, setValues] = useState<Record<string, string>>(
    Object.fromEntries(
      recordFields[kind].map((f) => [
        f.key,
        String(record?.data[f.key] ?? f.options?.[0] ?? ""),
      ]),
    ),
  );
  const [criteria, setCriteria] = useState<Criterion[]>(
    (record?.data.criteria as Criterion[]) ??
      technicalCriteria.map((criterion) => ({
        criterion,
        observation: "",
        initial: "",
        current: "",
        nextAction: "",
      })),
  );
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  async function save() {
    setError("");
    const data: Record<string, unknown> = {};
    for (const f of recordFields[kind])
      data[f.key] =
        f.type === "number"
          ? values[f.key] === ""
            ? null
            : Number(values[f.key])
          : (values[f.key] ?? "");
    if (kind === "technical") data.criteria = criteria;
    const parsed = recordSchemas[kind].safeParse(data);
    if (!parsed.success) {
      setError(parsed.error.issues.map((i) => i.message).join("; "));
      return;
    }
    setBusy(true);
    try {
      await api(
        `/students/${studentId}/records${record ? `/${record.id}` : ""}`,
        record ? "PUT" : "POST",
        { kind, date, data: parsed.data },
      );
      onSaved();
    } catch (e) {
      setError(message(e));
    } finally {
      setBusy(false);
    }
  }
  return (
    <>
      <Field label="Data (AAAA-MM-DD)" value={date} onChangeText={setDate} />
      <Fields
        fields={recordFields[kind]}
        values={values}
        setValues={setValues}
      />
      {kind === "monthly" && (
        <Notice>
          Adesão:{" "}
          {values.planned && values.completed
            ? (adherence(Number(values.planned), Number(values.completed)) ??
              "Sem previsão")
