  onSaved: (s: Student) => void;
}) {
  const [values, setValues] = useState<Record<string, string>>(
    student
      ? Object.fromEntries(
          Object.entries(student)
            .filter(
              ([, v]) =>
                typeof v === "string" || typeof v === "number" || v === null,
            )
            .map(([k, v]) => [k, String(v ?? "")]),
        )
      : {
          startDate: today(),
          weeklyFrequency: "3",
          status: "ativo",
          programId: "",
        },
  );
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  async function save() {
    setError("");
    const data = studentSchema.safeParse(values);
    if (!data.success) {
      setError(data.error.issues.map((i) => i.message).join("; "));
      return;
    }
    setBusy(true);
    try {
      onSaved(
        await api<Student>(
          student ? `/students/${student.id}` : "/students",
          student ? "PUT" : "POST",
          data.data,
        ),
      );
    } catch (e) {
      setError(message(e));
    } finally {
      setBusy(false);
    }
  }
  return (
    <>
      <Notice>
        Informações de saúde são opcionais e ficam restritas ao acompanhamento.
        Datas no formato AAAA-MM-DD.
      </Notice>
      {studentGroups.map((g) => (
        <Section title={g.title} key={g.title}>
          <Fields
            fields={g.fields.map(([key, label, type]) => ({
              key,
              label,
              type,
            }))}
            values={values}
            setValues={setValues}
          />
        </Section>
      ))}
      <Choices
        label="Status"
        value={values.status}
        onChange={(status) => setValues({ ...values, status })}
        options={["ativo", "pausado", "inativo"].map((value) => ({
          value,
          label: value,
        }))}
      />
      <Choices
        label="Programa vigente"
        value={values.programId ?? ""}
        onChange={(programId) => setValues({ ...values, programId })}
        options={[
          { value: "", label: "Sem programa" },
          ...programs.map((p) => ({ value: p.id, label: p.name })),
        ]}
      />
      <Notice error>{error}</Notice>
      <Button disabled={busy} onPress={() => void save()}>
        Salvar aluno
      </Button>
    </>
  );
}","source_path":"src/components/personal/forms.tsx","start_line":62}],"name":"Comportamento de StudentForm","parameters":[],"props":null,"related_symbols":[{"id":"ta-pago.code:src/components/personal/forms.tsx:component:Fields","name":"Fields"},{"id":"ta-pago.code:src/components/personal/forms.tsx:component:StudentForm","name":"StudentForm"},{"id":"ta-pago.code:src/components/personal/forms.tsx:function:StudentForm%2Fsave","name":"StudentForm/save"},{"id":"ta-pago.code:src/components/personal/ui.tsx:component:Button","name":"Button"},{"id":"ta-pago.code:src/components/personal/ui.tsx:component:Choices","name":"Choices"},{"id":"ta-pago.code:src/components/personal/ui.tsx:component:Notice","name":"Notice"},{"id":"ta-pago.code:src/components/personal/ui.tsx:component:Section","name":"Section"},{"id":"ta-pago.code:src/features/personal/student-fields.ts:constant:studentGroups","name":"studentGroups"}],"return_type":null,"route":null}

