              </Label>
            </Section>
          ))}
        </Dialog>
      )}
      {edit && (
        <Dialog title="Modelo de avaliação" onClose={() => setEdit(null)}>
          <TemplateForm
            template={edit === "new" ? undefined : edit}
            onSaved={() => {
              setEdit(null);
              void reload();
            }}
          />
        </Dialog>
      )}
    </Page>
  );
}

